// Random Queue Engine — สุ่มแบบไล่คิว ไม่ใช่ ORDER BY RANDOM() ทุกครั้ง
// + กันเล่นซ้ำ: ไม่เลือกวิดีโอที่อยู่ในประวัติ 10 รายการล่าสุด (ถ้ายังมีตัวอื่นเหลือ)
// สถานะคิว/ประวัติเก็บใน static data ของ workflow (รอดข้ามการรีสตาร์ท)
const res = $json || {};
const list = Array.isArray(res.videos) ? res.videos : (Array.isArray(res) ? res : []);
const src = $('Webhook รับคำขอ').first().json || {};
const q = (src.query && typeof src.query === 'object') ? src.query : {};
const sid = String(q.sid || q.session || 'anon').slice(0, 64);

const key = (v) => String(v.tiktokId || v.videoId || v.id || '');
const active = list.filter(v => v && (v.status ? v.status === 'active' : true) && key(v));

const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.recent)) sd.recent = [];
if (!Array.isArray(sd.queue)) sd.queue = [];

const ids = new Set(active.map(key));
sd.queue = sd.queue.filter(id => ids.has(id));          // ลบตัวที่ถูกปิด/ลบออกจากคลัง
let reshuffled = false;
if (!sd.queue.length) {                                  // คิวหมด → shuffle ใหม่
  sd.queue = active.map(key);
  for (let i = sd.queue.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [sd.queue[i], sd.queue[j]] = [sd.queue[j], sd.queue[i]];
  }
  reshuffled = true;
}

let pickKey = sd.queue.find(id => !sd.recent.includes(id));
if (!pickKey) { // กันซ้ำแล้วไม่เหลือตัวเลือก → อนุญาตให้วนซ้ำและล้างประวัติ
  pickKey = sd.queue[0] || sd.recent[0] || null;
  sd.recent = [];
}
if (pickKey) sd.queue = sd.queue.filter(id => id !== pickKey);
if (pickKey) { sd.recent.unshift(pickKey); sd.recent = sd.recent.slice(0, 10); }

const pick = active.find(v => key(v) === pickKey) || null;
return [{ json: {
  success: !!pick,
  sid,
  id: pick ? (pick.tiktokId || pick.videoId || key(pick)) : null,
  registerId: pick ? (pick.videoId || null) : null,
  title: pick ? pick.title : null,
  url: pick ? pick.url : null,
  embedUrl: pick ? (pick.embedUrl || (pick.tiktokId ? ('https://www.tiktok.com/player/v1/' + pick.tiktokId) : null)) : null,
  durationSec: pick ? (pick.durationSec || 30) : 0,
  username: "@aka989._",
  pool: { active: active.length, queueLeft: sd.queue.length, recent: sd.recent.length, reshuffled },
  reshuffled, queueLeft: sd.queue.length,
} }];

// อ้างผลจาก node คิวสุ่มโดยตรง (ไม่ใช้ $json เพราะ node ก่อนหน้าคือคำตอบของ /api/videos/played)
const p = $('คิวสุ่ม + กันซ้ำ 10 รายการ').first().json;
if (!p.success) return [{ json: { success: false, error: 'no_active_videos', allowAdd: true,
  hint: 'ยังไม่มีวิดีโอในคลัง — เพิ่มได้ที่ POST /webhook/add-video' } }];
return [{ json: { success: true, next: { id: p.id, url: p.url, embed_url: p.embedUrl, title: p.title, durationSec: p.durationSec }, pool: p.pool } }];
return [{ json: { success: true, username: p.username,
  video: { id: p.id, username: p.username, tiktok_url: p.url, url: p.url, embed_url: p.embedUrl,
           title: p.title, durationSec: p.durationSec },
  pool: p.pool } }];
